fn choose ( flag : bool ) -> i32 :
    if flag : 1 else : 0x7f

fn apply(callback: fn(i32) -> i32) -> i32: callback(1)

fn use_layout(flag: bool) -> i32:
    apply(
        (
            fn(value: i32):
                if flag: value else: 0
            ),
    )

data Box[T]:
    value: T

fn box[T](value: T) -> Box[T]:
    Box { value: value }

fn present[T](value: Box[T], flag: bool) -> bool:
    flag

fn box_all[Ts...](values: Ts...) -> (Box[Ts]...):
    pack.map((values...), box)

fn present_all[Ts...](values: Ts...) -> list[bool]:
    pack.map_list(boxes, present, true)
